import{PINS}from'./pins.mjs';import{createNightLayer,nightMix}from'./layer.mjs';const url=import.meta.url;const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
const entries=new WeakMap;
export async function prepareS1SharedNightBank({fetcher=fetch,signal}={}){
 const check=()=>{if(signal?.aborted)throw Error('S1_NIGHT_BANK_ABORTED')};const bank={};
 for(const [path,pin]of Object.entries(PINS)){check();const response=await fetcher(new URL(path,url),{signal});if(!response.ok)throw Error('S1_NIGHT_BANK_HTTP');const bytes=new Uint8Array(await response.arrayBuffer()).slice();check();if(bytes.length!==pin.bytes||await hash(bytes)!==pin.sha256)throw Error('S1_NIGHT_BANK_PIN');bank[path]=bytes;}
 check();const token=Object.freeze({}),entry={bank,refs:1,closed:false};entries.set(token,entry);let released=false;
 return Object.freeze({token,dispose(){if(released)return;released=true;release(token,entry)}});
}
function release(token,entry){if(--entry.refs===0){entries.delete(token);entry.bank=null;entry.closed=true}}
function claim(token){const e=entries.get(token);if(!e||e.closed)throw Error('S1_NIGHT_BANK_UNBRANDED');e.refs++;let released=false;return{bank:e.bank,dispose(){if(released)return;released=true;release(token,e)}}}
export async function loadS1Night({fetcher=fetch,signal,image,actors,sharedNightBankToken=null,extraForegroundAlpha=null,additionalActors=[],canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}){let closed=false,layer=null,bankLease=null;const check=()=>{if(closed||signal?.aborted)throw Error('S1_NIGHT_CANCELLED')};const read=async path=>{check();const r=await fetcher(new URL(path,url),{signal});if(!r.ok)throw Error('S1_NIGHT_MISSING');const b=new Uint8Array(await r.arrayBuffer()).slice();check();if(b.byteLength!==PINS[path].bytes||await hash(b)!==PINS[path].sha256)throw Error('S1_NIGHT_PIN');return b};const own=[];try{let bank;if(sharedNightBankToken!==null){check();bankLease=claim(sharedNightBankToken);bank=bankLease.bank}else{bank={};for(const p of Object.keys(PINS))bank[p]=await read(p)}const depth=JSON.parse(new TextDecoder().decode(bank['depth.json'])),copy=b=>b.buffer;layer=createNightLayer({ids:new Uint32Array(copy(bank['assets/light.u32'])),weights:new Float32Array(copy(bank['assets/light.f32'])),glass:bank['assets/lamp14-glass.u8'],ground:new Float32Array(copy(bank['assets/lamp14-ground.f32'])),depth,standardAlpha:bank['assets/standard-alpha.u8'],lamp14Alpha:bank['assets/lamp14-alpha.u8'],extraForegroundAlpha,additionalActors});const pixels=new Map(),alphas=new Map();for(const r of depth){if(r.alreadyRegistered)continue;const[w,h]=r.dimensions,c=canvasFactory(w,h);own.push(c);const g=c.getContext('2d');g.drawImage(image,...r.origin,w,h,0,0,w,h);pixels.set(r.id,g.getImageData(0,0,w,h).data);c.width=c.height=1;own.pop()}for(const[id,actor]of Object.entries(actors)){const c=canvasFactory(107,107);own.push(c);const g=c.getContext('2d');g.drawImage(actor,0,0);const rgba=g.getImageData(0,0,107,107).data;alphas.set(id,Uint8Array.from({length:11449},(_,i)=>rgba[i*4+3]));c.width=c.height=1;own.pop()}check();return{drawDepth(ctx,camera,foot){check();layer.drawDepth(ctx,r=>pixels.get(r.id),camera,foot)},apply(ctx,camera,{foot,frame,minutes=720,lights=true,rest=false}){check();if(rest||nightMix(minutes)===0)return{mix:0,lightRows:0};if(!Number.isFinite(minutes))throw Error('S1_NIGHT_CLOCK');const im=ctx.getImageData(0,0,960,540),result=layer.apply(im.data,camera,{minutes,lights,rest,foot,actorAlpha:alphas.get('actor:'+frame),actorOrigin:[foot[0]-camera[0]-53,foot[1]-camera[1]-90]});if(result.mix)ctx.putImageData(im,0,0);return result},dispose(){if(closed)return;closed=true;layer.dispose();pixels.clear();alphas.clear();bankLease?.dispose();bankLease=null}}}catch(e){closed=true;layer?.dispose();bankLease?.dispose();bankLease=null;for(const c of own)c.width=c.height=1;throw e}}
